/**
 * Input validation shared by the browser and the API (one set of rules, both
 * sides). Everything a visitor or a URL can send is checked here before it is
 * used: identifiers have strict formats, request bodies accept only known
 * keys, and redirects are limited to this site or to Stripe Checkout.
 *
 * Nothing in this file trusts or repairs suspicious input: it is rejected.
 */
import { getOffer } from './offers.js';

/** Purchase attempt id: a v4-style UUID generated by crypto.randomUUID(). */
export const ATTEMPT_ID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** Stripe Checkout Session id. */
export const SESSION_ID_RE = /^cs_(test|live)_[A-Za-z0-9]{10,200}$/;

/**
 * Where the browser may be sent to pay. Stripe-hosted Checkout only; if a
 * custom Checkout domain is configured in Stripe one day, add it here.
 */
export const STRIPE_CHECKOUT_ORIGINS = Object.freeze(['https://checkout.stripe.com']);

/** Path of the confirmation page, the only internal redirect the API returns. */
export const CONFIRMATION_PATH = '/paiement/confirmation';

const CHECKOUT_KEYS = Object.freeze(['offerId', 'attemptId', 'sessionId']);

// C0/C1 controls, zero-width and bidirectional formatting characters.
const UNSAFE_RANGES = [
  [0x00, 0x1f], [0x7f, 0x9f], [0xad, 0xad], [0x200b, 0x200f],
  [0x2028, 0x202e], [0x2060, 0x2064], [0x2066, 0x206f], [0xfeff, 0xfeff]
];
const hex = (c) => '\\u' + c.toString(16).padStart(4, '0');
const UNSAFE_CHARS_RE = new RegExp(`[${UNSAFE_RANGES.map(([a, b]) => (a === b ? hex(a) : `${hex(a)}-${hex(b)}`)).join('')}]`);

export function hasUnsafeChars(value) {
  return typeof value === 'string' && UNSAFE_CHARS_RE.test(value);
}

export function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

/** True when `obj` has no own key outside `allowed` (catches __proto__ too). */
export function hasOnlyKeys(obj, allowed) {
  return Object.keys(obj).every((k) => allowed.includes(k));
}

export function isAttemptId(value) {
  return typeof value === 'string' && value.length === 36 && ATTEMPT_ID_RE.test(value);
}

export function isSessionId(value) {
  return typeof value === 'string' && value.length <= 210 && SESSION_ID_RE.test(value);
}

/**
 * Strict schema for POST /api/stripe/create-checkout-session.
 * Body: { offerId: catalog id, attemptId: uuid, sessionId?: cs_... | null }.
 * Any other key (a price, a name, __proto__...) makes the request invalid.
 *
 * @returns {{ ok: true, value: { offerId: string, attemptId: string, sessionId: string | null } } | { ok: false }}
 */
export function parseCheckoutRequest(body) {
  if (!isPlainObject(body) || !hasOnlyKeys(body, CHECKOUT_KEYS)) return { ok: false };
  const { offerId, attemptId, sessionId } = body;
  if (typeof offerId !== 'string' || offerId.length > 64 || !getOffer(offerId)) return { ok: false };
  if (!isAttemptId(attemptId)) return { ok: false };
  if (sessionId !== undefined && sessionId !== null && !isSessionId(sessionId)) return { ok: false };
  return { ok: true, value: { offerId, attemptId: attemptId.toLowerCase(), sessionId: sessionId ?? null } };
}

/** A URL the browser may be sent to for payment: https on a Stripe Checkout origin. */
export function isStripeCheckoutUrl(value) {
  if (typeof value !== 'string' || value.length > 2048 || hasUnsafeChars(value)) return false;
  let url;
  try {
    url = new URL(value);
  } catch {
    return false;
  }
  return url.protocol === 'https:' && !url.username && !url.password && STRIPE_CHECKOUT_ORIGINS.includes(url.origin);
}

/** `/paiement/confirmation?session_id=<valid id>`, exactly. */
export function confirmationPath(sessionId) {
  return `${CONFIRMATION_PATH}?session_id=${encodeURIComponent(sessionId)}`;
}

export function isConfirmationPath(value) {
  if (typeof value !== 'string' || !value.startsWith(`${CONFIRMATION_PATH}?`)) return false;
  const params = new URLSearchParams(value.slice(CONFIRMATION_PATH.length + 1));
  const keys = [...params.keys()];
  return keys.length === 1 && keys[0] === 'session_id' && isSessionId(params.get('session_id'));
}

/**
 * Reads `session_id` from a query string. Returns '' unless it is the only
 * occurrence and has the Stripe format.
 */
export function readSessionIdParam(search) {
  if (typeof search !== 'string' || search.length > 512) return '';
  const values = new URLSearchParams(search).getAll('session_id');
  return values.length === 1 && isSessionId(values[0]) ? values[0] : '';
}

/**
 * Internal path for in-site navigation: "/x...", never "//host", "/\\host",
 * a scheme (javascript:, data:...) or control characters. Anything else
 * returns `fallback`.
 */
export function safeInternalPath(value, fallback = '/') {
  if (typeof value !== 'string' || value.length > 2048 || hasUnsafeChars(value)) return fallback;
  if (!value.startsWith('/') || value.startsWith('//') || value.includes('\\')) return fallback;
  try {
    const base = 'https://internal.invalid';
    const url = new URL(value, base);
    if (url.origin !== base) return fallback;
    return `${url.pathname}${url.search}${url.hash}`;
  } catch {
    return fallback;
  }
}

/** Shape of a GET /api/stripe/session-status answer the page may display. */
export function parseSessionStatus(data) {
  if (!isPlainObject(data)) return null;
  const { state, offerId, amount, currency } = data;
  if (!['paid', 'processing', 'open', 'expired'].includes(state)) return null;
  if (typeof offerId !== 'string' || !getOffer(offerId)) return null;
  if (state === 'paid' && (!Number.isSafeInteger(amount) || amount < 0 || amount > 100_000_000)) return null;
  if (state === 'paid' && (typeof currency !== 'string' || !/^[a-z]{3}$/.test(currency))) return null;
  return { state, offerId, amount, currency };
}
